// Generates lib/l10n/runtime_localizations.dart from the gen-l10n output
// lib/l10n/app_localizations.dart (ADR 0101). Run after changing the ARB files:
//
//   flutter gen-l10n && dart run tool/gen_runtime_l10n.dart
//
// test/runtime_l10n_test.dart fails when the generated file is out of date.
import 'dart:io';

/// The generated source for the abstract class in [appLocalizations].
String generateRuntimeLocalizations(String appLocalizations) {
  final member = RegExp(
    r'^  String (?:get (\w+)|(\w+)\(([^)]*)\));',
    multiLine: true,
  );
  final out = StringBuffer()
    ..writeln('// GENERATED by tool/gen_runtime_l10n.dart from app_localizations.dart.')
    ..writeln('// Do not edit; run `dart run tool/gen_runtime_l10n.dart` after flutter gen-l10n.')
    ..writeln('// ignore_for_file: type=lint')
    ..writeln()
    ..writeln("import 'app_localizations.dart';")
    ..writeln("import 'icu.dart';")
    ..writeln()
    ..writeln('/// Answers every message from a runtime [catalogue] (ADR 0101) when it has the key, and')
    ..writeln('/// from [base] (a shipped localization) otherwise. A malformed runtime message falls')
    ..writeln('/// back to [base] too.')
    ..writeln('class RuntimeAppLocalizations extends AppLocalizations {')
    ..writeln('  RuntimeAppLocalizations(super.locale, this.base, this.catalogue);')
    ..writeln()
    ..writeln('  final AppLocalizations base;')
    ..writeln('  final Map<String, String> catalogue;')
    ..writeln()
    ..writeln('  String? _m(String key, Map<String, Object?> args) {')
    ..writeln('    final text = this.catalogue[key];')
    ..writeln('    if (text == null) return null;')
    ..writeln('    try {')
    ..writeln('      return formatIcu(text, args, localeName);')
    ..writeln('    } on FormatException {')
    ..writeln('      return null;')
    ..writeln('    }')
    ..writeln('  }');
  final keys = <String>[];
  for (final m in member.allMatches(appLocalizations)) {
    final getter = m.group(1);
    if (getter != null) {
      keys.add(getter);
      out
        ..writeln()
        ..writeln('  @override')
        ..writeln(
          "  String get $getter => _m('$getter', const {}) ?? this.base.$getter;",
        );
      continue;
    }
    final name = m.group(2)!;
    keys.add(name);
    final params = m
        .group(3)!
        .split(',')
        .map((p) => p.trim())
        .where((p) => p.isNotEmpty)
        .toList();
    final names = [for (final p in params) p.split(RegExp(r'\s+')).last];
    final args = names.map((n) => "'$n': $n").join(', ');
    out
      ..writeln()
      ..writeln('  @override')
      ..writeln('  String $name(${params.join(', ')}) =>')
      ..writeln(
        "      _m('$name', {$args}) ?? this.base.$name(${names.join(', ')});",
      );
  }
  out
    ..writeln('}')
    ..writeln()
    ..writeln('/// Every message key of the app, in the order of the generated localizations.')
    ..writeln('const runtimeMessageKeys = <String>[');
  for (final k in keys) {
    out.writeln("  '$k',");
  }
  out.writeln('];');
  return out.toString();
}

void main() {
  final source = File('lib/l10n/app_localizations.dart').readAsStringSync();
  File(
    'lib/l10n/runtime_localizations.dart',
  ).writeAsStringSync(generateRuntimeLocalizations(source));
}
